@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class DeepDevicesClient {
    static int pausedAmmo;static int ticks,stage;static long due;static LivingEntity victim;static GrappleProjectile grapple;static TurretEntity turret;static FluxRiftEntity rift;static ItemStack bag;static FocalEntity table;
    static void position(ServerPlayer p){p.teleportTo(p.level(),128.5,205,8.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);}
    static void clearShots(ServerLevel l){for(var e:l.getEntitiesOfClass(FocusProjectile.class,new AABB(Q).inflate(50)))e.discard();}
    static void cast(ServerPlayer p,FocusProgram spell){PlanProbe.equip(p,spell);AuraManager.addVis(p.level(),p.blockPosition(),1000);float before=AuraManager.get(p.level(),p.blockPosition()).vis();check(p.getMainHandItem().getItem().use(p.level(),p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS,"Deep cast failed");check(Math.abs(before-AuraManager.get(p.level(),p.blockPosition()).vis()-spell.vis())<.003,"Deep graph aura paid more than once");}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!System.getProperty("thaumcraft.thaumaturgyProbe","").equals("deep-client")||e.server().isDedicatedServer()||e.server().getPlayerList().getPlayers().isEmpty()||++ticks<80)return;var p=e.server().getPlayerList().getPlayers().getFirst();var l=p.level();long now=l.getGameTime();
        if(stage==0){l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.SPAWN_MOBS,false,e.server());l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.SPAWN_PHANTOMS,false,e.server());for(var mob:l.getEntitiesOfClass(LivingEntity.class,new AABB(Q).inflate(60)))if(mob!=p)mob.discard();clearShots(l);for(var q:BlockPos.betweenClosed(Q.offset(-12,-1,-4),Q.offset(24,7,24)))l.setBlockAndUpdate(q,q.getY()==204?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());position(p);knowledge(p);rareEarth(p);p.setGameMode(GameType.SURVIVAL);p.setHealth(20);p.getFoodData().setFoodLevel(10);for(var s:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET))p.setItemSlot(s,ItemStack.EMPTY);pouch(p);bag=p.getMainHandItem().copy();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get("pech_wand").get(),2));check(p.getMainHandItem().getItem().use(l,p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS&&p.getMainHandItem().getCount()==1&&ResearchService.state(p).flags().contains("!Pechwand"),"Pech study not consumed/unlocked");l.setBlockAndUpdate(Q.offset(0,1,4),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(Q.offset(0,1,8),Blocks.STONE.defaultBlockState());victim=BatRiftClient.mob(p,p.position().add(0,0,10));cast(p,graph());stage=1;due=now+25;return;}
        if(stage==1&&now>=due){check(l.isEmptyBlock(Q.offset(0,1,4))&&l.isEmptyBlock(Q.offset(0,1,8))&&victim.getHealth()==19,"Projectile -> Bolt -> Touch continuation did not execute remotely: "+victim.getHealth());victim.discard();clearShots(l);l.setBlockAndUpdate(Q.offset(0,1,4),Blocks.STONE.defaultBlockState());cast(p,node("bolt","air").withChild(0,node("projectile","earth").modifier("scatter")));var shots=l.getEntitiesOfClass(FocusProjectile.class,new AABB(Q).inflate(32));check(shots.size()==2&&shots.stream().allMatch(s->s.getZ()>11.8),"Nested Scatter did not spawn from impact");clearShots(l);l.setBlockAndUpdate(Q.offset(0,1,4),Blocks.AIR.defaultBlockState());position(p);for(var q:BlockPos.betweenClosed(Q.offset(-2,2,10),Q.offset(2,6,10)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());var gun=item("grapple_gun");gun.set(DeviceContent.CHARGE.get(),3);p.setItemInHand(InteractionHand.MAIN_HAND,gun);p.setXRot(-17);check(gun.getItem().use(l,p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS&&RechargeHelper.getCharge(gun)==2,"Grapple did not consume one charge");grapple=l.getEntitiesOfClass(GrappleProjectile.class,new AABB(Q).inflate(40)).getFirst();stage=2;due=now+40;Thaumcraft.LOGGER.info("DEEP_EXECUTION_OK: remote three-level chain, nested Scatter and one aura payment; Pech study unlocked");return;}
        if(stage==2){if(!grapple.anchored()){check(!grapple.isRemoved()&&now<due,"Grapple failed to attach");return;}var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,p.registryAccess());grapple.saveWithoutId(out);var copy=new GrappleProjectile(ThaumaturgyContent.GRAPPLE.get(),l);copy.load(TagValueInput.create(ProblemReporter.DISCARDING,p.registryAccess(),out.buildResult()));check(copy.anchored(),"Grapple anchor snapshot lost");stage=3;due=now+3;return;}
        if(stage==3&&now>=due){check(!grapple.isRemoved()&&p.getDeltaMovement().length()>.05&&p.fallDistance==0,"Grapple did not pull/reset fall distance");p.setShiftKeyDown(true);grapple.tick();check(grapple.isRemoved(),"Sneak failed to release grapple");p.setShiftKeyDown(false);position(p);var q=Q.west(4);p.setItemInHand(InteractionHand.MAIN_HAND,item("turret_basic"));var hit=new BlockHitResult(Vec3.atCenterOf(q.below()),Direction.UP,q.below(),false);p.gameMode.useItemOn(p,l,p.getMainHandItem(),InteractionHand.MAIN_HAND,hit);check(l.getBlockEntity(q) instanceof TurretEntity,"Native turret placement failed");turret=(TurretEntity)l.getBlockEntity(q);check(p.getUUID().equals(turret.owner()),"Placed turret lost owner");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.ARROW,16));p.gameMode.useItemOn(p,l,p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(q),Direction.UP,q,false));check(turret.ammo()==16&&p.getMainHandItem().isEmpty(),"Native turret arrow loading failed");victim=BatRiftClient.mob(p,Vec3.atCenterOf(q).add(0,-.5,10));stage=4;due=now+120;Thaumcraft.LOGGER.info("DEEP_GRAPPLE_OK: physical attachment, charge, anchor persistence, pull and sneak release");return;}
        if(stage==4){if(victim.getHealth()==20){check(now<due,"Turret failed to hit after several shots; ammo="+turret.ammo());return;}check(turret.ammo()<16&&victim.getHealth()<20,"Turret failed to consume ammunition or hit target: "+victim.getHealth()+" / "+turret.ammo());pausedAmmo=turret.ammo();l.setBlockAndUpdate(turret.getBlockPos().east(),Blocks.REDSTONE_BLOCK.defaultBlockState());stage=5;due=now+50;return;}
        if(stage==5&&now>=due){check(turret.ammo()==pausedAmmo,"Powered turret did not pause");victim.discard();var q=Q.east(4);p.setItemInHand(InteractionHand.MAIN_HAND,item("turret_advanced"));p.gameMode.useItemOn(p,l,p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(q.below()),Direction.UP,q.below(),false));var advanced=(TurretEntity)l.getBlockEntity(q);check(advanced!=null&&advanced.advanced(),"Advanced turret placement failed");advanced.interact(p,new ItemStack(Items.STICK));check(advanced.mode()==1,"Advanced mode change failed");p.teleportTo(l,144.5,205,8.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);l.setBlockAndUpdate(new BlockPos(144,206,13),Blocks.BEDROCK.defaultBlockState());l.setBlockAndUpdate(new BlockPos(144,205,13),Blocks.BEDROCK.defaultBlockState());rift=new FluxRiftEntity(RiftContent.RIFT.get(),l);rift.setPos(144.5,206.5,12.5);rift.setSize(25);rift.setStability(100);l.addFreshEntity(rift);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get("causality_collapser").get(),2));var bomb=p.getMainHandItem();check(bomb.getItem().use(l,p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS&&bomb.getCount()==1,"Collapser not consumed");check(bomb.getItem().use(l,p,InteractionHand.MAIN_HAND)==InteractionResult.FAIL&&bomb.getCount()==1,"Collapser cooldown bypassed");position(p);stage=6;due=now+35;Thaumcraft.LOGGER.info("DEEP_TURRETS_OK: native placement/loading, actual arrow damage, ammunition, redstone and advanced configuration");return;}
        if(stage==6){check(now<due,"Collapser failed to close nearby rift");if(!rift.collapsing()||rift.size()==25)return;check(rift.size()<25,"Rift did not shrink after collapse");stage=7;due=now+60;return;}
        if(stage==7){if(!rift.isRemoved()){check(now<due,"Rift collapse did not finish");return;}check(!l.getEntitiesOfClass(ItemEntity.class,new AABB(new BlockPos(144,206,12)).inflate(5),x->x.getItem().is(thaumcraft.content.SimpleContent.ITEMS.get("void_seed").get())).isEmpty(),"Rift did not produce native collapse loot");l.setBlockAndUpdate(Q,ThaumaturgyContent.TABLE.get().defaultBlockState());table=(FocalEntity)l.getBlockEntity(Q);costs(p,table);stage=8;Thaumcraft.LOGGER.info("DEEP_COLLAPSER_OK: native throwable, cooldown, nearby rift collapse and loot");return;}
        if(stage==8&&!table.working()){check(graph().equals(table.inventory.getItem(0).get(ThaumaturgyContent.PROGRAM.get())),"Deep crafted focus mismatch");p.setGameMode(GameType.CREATIVE);p.openMenu(table);stage=9;Thaumcraft.LOGGER.info("DEEP_CLIENT_OK: all graph and device mechanics complete; inspect Graph page");}
        if(stage==9&&p.containerMenu instanceof net.minecraft.world.inventory.InventoryMenu){p.setItemInHand(InteractionHand.MAIN_HAND,bag);bag.getItem().use(l,p,InteractionHand.MAIN_HAND);stage=10;Thaumcraft.LOGGER.info("DEEP_POUCH_GUI_READY");}
    }
    @SubscribeEvent public static void impact(net.minecraftforge.event.entity.ProjectileImpactEvent e){if(System.getProperty("thaumcraft.thaumaturgyProbe","").equals("deep-client")&&e.getProjectile() instanceof TurretArrow a&&!a.level().isClientSide())Thaumcraft.LOGGER.info("DEEP_ARROW_IMPACT: {} at {} victim={}",e.getRayTraceResult().getType(),e.getRayTraceResult().getLocation(),e.getRayTraceResult() instanceof EntityHitResult h?h.getEntity().getType():"block");}
}
